import * as THREE from 'three'
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js'
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js'
import { uvMetres, type MaterialKey } from '../materials/materials'

/**
 * Architectural part builder.
 *
 * Parts are declared in world metres (Y up, floor level at y = 0.45) and are
 * merged per material into a handful of meshes. UVs are generated by box
 * projection in metres so a 1.2 m timber texture is always 1.2 m on any part,
 * and the grain direction can be set per part (`grain`).
 */
export type Axis = 'x' | 'y' | 'z'
export type Vec3 = [number, number, number]

export interface BoxOptions {
  /** Edge radius in metres. Bevels catch highlights on close-up parts. */
  bevel?: number
  /** World axis the timber grain (texture V) follows. Default 'y'. */
  grain?: Axis
  /** Rotation about Y in radians, applied around the box centre. */
  rotY?: number
  /** Casts shadows (default true). */
  cast?: boolean
}

interface Part {
  geo: THREE.BufferGeometry
  cast: boolean
}

const AXES: Axis[] = ['x', 'y', 'z']

function hash(a: number, b: number, c: number) {
  const s = Math.sin(a * 12.9898 + b * 78.233 + c * 37.719) * 43758.5453
  return s - Math.floor(s)
}

/**
 * Writes metre-scaled UVs by box projection: each vertex uses the two axes
 * perpendicular to its dominant normal; V follows `grain` where possible.
 * Coordinates are in the part's local frame (plus `origin`) so textures stay
 * continuous across neighbouring parts but follow a rotated part.
 */
function projectUVs(geo: THREE.BufferGeometry, metres: number, grain: Axis, origin: Vec3, jitter: number) {
  const pos = geo.attributes.position
  const nor = geo.attributes.normal
  const uv = new Float32Array(pos.count * 2)
  for (let i = 0; i < pos.count; i++) {
    const p = [pos.getX(i) + origin[0], pos.getY(i) + origin[1], pos.getZ(i) + origin[2]]
    const n = [Math.abs(nor.getX(i)), Math.abs(nor.getY(i)), Math.abs(nor.getZ(i))]
    const dominant = n[0] >= n[1] && n[0] >= n[2] ? 0 : n[1] >= n[2] ? 1 : 2
    const g = AXES.indexOf(grain)
    let vAxis = g
    if (vAxis === dominant) vAxis = dominant === 1 ? 2 : 1
    const uAxis = [0, 1, 2].find((a) => a !== dominant && a !== vAxis)!
    uv[i * 2] = p[uAxis] / metres + jitter
    uv[i * 2 + 1] = p[vAxis] / metres + jitter * 0.37
  }
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2))
}

export class PartBuilder {
  private parts = new Map<MaterialKey, Part[]>()

  box(key: MaterialKey, center: Vec3, size: Vec3, opts: BoxOptions = {}) {
    const [w, h, d] = size
    const r = Math.min(opts.bevel ?? 0, Math.min(w, h, d) / 2 - 1e-4)
    const geo = r > 0 ? new RoundedBoxGeometry(w, h, d, 2, r) : new THREE.BoxGeometry(w, h, d)
    const jitter = hash(center[0], center[1], center[2]) * 3
    projectUVs(geo, uvMetres[key], opts.grain ?? 'y', [0, 0, 0], jitter)
    if (opts.rotY) geo.rotateY(opts.rotY)
    geo.translate(center[0], center[1], center[2])
    this.push(key, geo, opts.cast ?? true)
    return this
  }

  /** Box from min/max corners — convenient for walls and slabs. */
  span(key: MaterialKey, min: Vec3, max: Vec3, opts: BoxOptions = {}) {
    const c: Vec3 = [(min[0] + max[0]) / 2, (min[1] + max[1]) / 2, (min[2] + max[2]) / 2]
    const s: Vec3 = [max[0] - min[0], max[1] - min[1], max[2] - min[2]]
    // UVs for span parts are projected in world space so long walls built
    // from several spans read as one continuous surface.
    const geo = (opts.bevel ?? 0) > 0 ? null : new THREE.BoxGeometry(s[0], s[1], s[2])
    if (!geo) return this.box(key, c, s, opts)
    projectUVs(geo, uvMetres[key], opts.grain ?? 'y', c, 0)
    geo.translate(c[0], c[1], c[2])
    this.push(key, geo, opts.cast ?? true)
    return this
  }

  /** Arbitrary geometry with a transform (lathe ceramics, door leaf, etc.). */
  geometry(key: MaterialKey, geo: THREE.BufferGeometry, matrix?: THREE.Matrix4, cast = true, grain: Axis = 'y') {
    // Re-project UVs in metres (local frame) unless the geometry brings its own
    // meaningful UVs (lathe-turned ceramics keep theirs).
    if (!geo.attributes.uv || !geo.userData.keepUV) projectUVs(geo, uvMetres[key], grain, [0, 0, 0], 0)
    if (matrix) geo.applyMatrix4(matrix)
    this.push(key, geo, cast)
    return this
  }

  private push(key: MaterialKey, geo: THREE.BufferGeometry, cast: boolean) {
    // Normalise to non-indexed so box, rounded box and lathe parts can merge.
    const g = geo.index ? geo.toNonIndexed() : geo
    if (g !== geo) geo.dispose()
    for (const name of Object.keys(g.attributes)) {
      if (name !== 'position' && name !== 'normal' && name !== 'uv') g.deleteAttribute(name)
    }
    g.clearGroups()
    const list = this.parts.get(key) ?? []
    list.push({ geo: g, cast })
    this.parts.set(key, list)
  }

  /** Merges parts into one geometry per (material, castShadow) pair. */
  build() {
    const out: { key: MaterialKey; geometry: THREE.BufferGeometry; cast: boolean }[] = []
    for (const [key, list] of this.parts) {
      for (const cast of [true, false]) {
        const geos = list.filter((p) => p.cast === cast).map((p) => p.geo)
        if (!geos.length) continue
        const merged = mergeGeometries(geos, false)
        if (!merged) continue
        merged.computeBoundingSphere()
        out.push({ key, geometry: merged, cast })
        geos.forEach((g) => g.dispose())
      }
    }
    this.parts.clear()
    return out
  }
}
